import { db } from "./db";
import { activeWhere } from "./subscription";
import { parseDoctorQuery, specialtyMatches } from "./intent";
import { HttpError } from "./guard";
import { FEE } from "./pricing";
import { signToken } from "./aitoken";
import { doctorSlotWhere } from "./bookingFlow";

// Real MediHome doctors only. Nothing here is ever generated by the model.
export async function findDoctors(text: string) {
  const hospitals = await db.hospital.findMany({ where: activeWhere(), select: { id: true, name: true, location: true } });
  const q = parseDoctorQuery(text, hospitals);
  if (!q.wants) return { intent: false as const };
  if (q.needsLocation) return { intent: true as const, needsLocation: true, doctors: [] as any[] };
  const rows = await db.doctor.findMany({
    where: { published: true, hospital: activeWhere(), ...(q.hospitalIds.length ? { hospitalId: { in: q.hospitalIds } } : {}) },
    include: { hospital: { select: { id: true, name: true, location: true } } }, take: 100, orderBy: { createdAt: "desc" },
  });
  const doctors = rows.filter((d) => !q.keys.length || q.keys.some((k) => specialtyMatches(d.specialty, k))).slice(0, 6).map((d) => ({
    id: d.id, name: d.name, specialty: d.specialty, qualification: d.qualification, experience: d.experience, feeBdt: d.feeBdt,
    visitingDays: d.visitingDays, visitingHours: d.visitingHours, slots: d.slots.split(",").map((s) => s.trim()).filter(Boolean),
    hospital: { id: d.hospital.id, name: d.hospital.name, location: d.hospital.location },
  }));
  return { intent: true as const, needsLocation: false, doctors, filtered: { specialties: q.keys, hospitals: q.hospitalIds.length } };
}

// Step 1 of booking: re-check everything on the server and issue a signed confirmation token. Nothing is booked yet.
export async function prepareBooking(userId: string, b: any) {
  const d = await db.doctor.findFirst({ where: { id: String(b.doctorId || ""), published: true, hospital: activeWhere() }, include: { hospital: { select: { id: true, name: true, location: true } } } });
  if (!d) throw new HttpError(404, "This doctor is not available any more");
  const date = String(b.date || ""), time = String(b.time || ""), today = new Date().toISOString().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date < today) throw new HttpError(400, "Choose a valid future date");
  const slots = d.slots.split(",").map((s) => s.trim()).filter(Boolean);
  if (slots.length && !slots.includes(time)) throw new HttpError(400, "Choose one of the listed time slots");
  const clash = await db.booking.findFirst({ where: doctorSlotWhere(d.id, new Date(date + "T00:00:00Z"), time || null) });
  if (clash) throw new HttpError(409, "That slot is already taken. Please choose another.");
  return {
    summary: { doctor: d.name, specialty: d.specialty, qualification: d.qualification, hospital: d.hospital.name, location: d.hospital.location, date, time, consultationFeeBdt: d.feeBdt, serviceFeeBdt: FEE() },
    token: signToken({ uid: userId, doctorId: d.id, hospitalId: d.hospitalId, date, time }),
  };
}
